<?php
use App\Core\Auth;
use App\Core\Authorization;
use App\Core\Csrf;
use App\Core\Database;
use App\Core\Env;
$requestPath='/' . trim((string)parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH),'/');
$applicationBase=rtrim((string)parse_url(Env::get('APP_URL',''),PHP_URL_PATH),'/');
if($applicationBase!==''&&str_starts_with($requestPath,$applicationBase)){$requestPath=substr($requestPath,strlen($applicationBase))?:'/';}
$active=static fn(string $needle):string=>preg_match('#^'.preg_quote($needle,'#').'(?:/|$)#',$requestPath)?' active':'';
$branding=[];
$logoStatement=Database::connection()->query('SELECT setting_key,setting_value FROM system_settings WHERE setting_key IN ("school_logo","school_logo_position_y","school_name")');
foreach($logoStatement->fetchAll() as $setting){$branding[$setting['setting_key']]=$setting['setting_value'];}
$schoolLogo=$branding['school_logo']??null;
$schoolLogoPositionY=max(0,min(100,(int)($branding['school_logo_position_y']??50)));
$schoolName=trim((string)($branding['school_name']??''))?:'School Management';
$studentNavId=Auth::check()&&Authorization::isStudentOnly()?Authorization::ownStudentId():null;
$studentNavHref=$studentNavId!==null?'/students/'.$studentNavId:'/students';
$studentNavLabel=Auth::check()&&Authorization::isStudentOnly()?'My profile':(Auth::check()&&Authorization::isTeacherOnly()?'My assigned students':'Students');
$teacherNavId=Auth::check()&&Authorization::isTeacherOnly()?Authorization::ownTeacherId():null;
$teacherNavHref=$teacherNavId!==null?'/teachers/'.$teacherNavId:'/teachers';
$teacherNavLabel=Auth::check()&&Authorization::isTeacherOnly()?'My profile':'Teachers';
$styles=['app.css','modules.css'];
if(str_starts_with($requestPath,'/attendance')) $styles[]='attendance.css';
if(str_starts_with($requestPath,'/events')) $styles[]='events.css';
if(str_starts_with($requestPath,'/reports')) $styles[]='reports.css';
if(str_starts_with($requestPath,'/admin/settings')||str_starts_with($requestPath,'/admin/audit')||str_starts_with($requestPath,'/admin/backups')||str_starts_with($requestPath,'/dashboard')) $styles[]='operations.css';
$styles[]='navigation.css';
$styles[]='theme-purple.css';
if(str_starts_with($requestPath,'/dashboard')){$styles[]='dashboard-purple.css';$styles[]='birthdays.css';}
$styles[]='branding.css?v=4';
$styles[]='layout-fixes.css';
if(str_starts_with($requestPath,'/tuition')){$styles[]='tuition.css?v=2';$styles[]='tuition-compact.css?v=1';$styles[]='tuition-form.css?v=1';}
if(str_starts_with($requestPath,'/insurance')){$styles[]='insurance.css';$styles[]='insurance-fixes.css';}
if(str_starts_with($requestPath,'/uniform-id')||str_starts_with($requestPath,'/students')||str_starts_with($requestPath,'/teachers')) $styles[]='inventory.css?v=4';
if(str_starts_with($requestPath,'/students')) $styles[]='students.css?v=2';
if(str_starts_with($requestPath,'/teachers')) $styles[]='teachers.css?v=1';
if(str_contains($requestPath,'/import')) $styles[]='imports.css';
$styles[]='sidebar-modern.css?v=2';
$styles[]='ui-polish.css?v=3';
?>
