(()=>{const body=document.body,toggles=[...document.querySelectorAll('[data-menu-toggle]')],menuButton=document.querySelector('.menu-button'),sidebar=document.getElementById('app-sidebar');const setMenu=open=>{body.classList.toggle('menu-open',open);menuButton?.setAttribute('aria-expanded',String(open));menuButton?.setAttribute('aria-label',open?'Close navigation':'Open navigation');if(open)sidebar?.querySelector('a')?.focus();else if(document.activeElement&&sidebar?.contains(document.activeElement))menuButton?.focus();};toggles.forEach(button=>button.addEventListener('click',()=>setMenu(!body.classList.contains('menu-open'))));sidebar?.querySelectorAll('a').forEach(link=>link.addEventListener('click',()=>{if(matchMedia('(max-width: 800px)').matches)setMenu(false)}));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&body.classList.contains('menu-open'))setMenu(false)});
const statusGroups={success:['active','paid','present','published','completed','returned','approved','enabled','primary','system'],warning:['pending','draft','ongoing','open','under review','submitted','on leave','expiring soon'],danger:['inactive','expired','cancelled','withdrawn','separated','rejected','locked','absent','overdue'],info:['teacher','student','staff','invited','late','excused','graduated','transferred'],neutral:['unrecorded','waived']};document.querySelectorAll('.badge').forEach(badge=>{const value=badge.textContent.trim().toLowerCase().replaceAll('_',' ');for(const [group,values] of Object.entries(statusGroups)){if(values.includes(value)){badge.classList.add('status-'+group);break;}}});document.querySelectorAll('.alert.danger').forEach(alert=>alert.setAttribute('role','alert'));document.querySelectorAll('thead th:last-child:empty').forEach(th=>{th.textContent='Actions';th.classList.add('action-column')});})();
</script></body></html>
